"""On-demand time and encoding-choice details; never change processing."""
STYLE='<style>.result-insights{margin:12px 0;padding:12px;border:1px solid var(--hairline);min-width:0}.result-insights h4{margin:8px 0}.insight-times{margin:8px 0}.insight-times>div{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px 12px;margin:8px 0}.insight-times dt,.insight-times dd{margin:0}.insight-track{grid-column:1/-1;height:5px;background:var(--hairline)}.insight-track>span{display:block;height:100%;background:var(--accent)}.insight-table-wrap{max-width:100%;overflow:auto}.insight-table-wrap table{width:100%;min-width:540px;border-collapse:collapse;font-size:.85rem}.insight-table-wrap th,.insight-table-wrap td{text-align:left;padding:8px;border-bottom:1px solid var(--hairline);vertical-align:top}.insight-note{font-size:.8rem;color:var(--muted);line-height:1.5}.insight-scroll-hint{display:none}@media(max-width:640px){.insight-scroll-hint{display:block}}</style>'
SCRIPT=r'''<script>
function insightDuration(n){if(!Number.isFinite(n)||n<0)return 'Not measured';if(n===0)return '0s';if(n<1)return 'Less than 1s';n=Math.round(n);return (n>=3600?Math.floor(n/3600)+'h ':'')+(n>=60?Math.floor(n%3600/60)+'m ':'')+(n%60)+'s'}
function renderResultInsights(box,body){
 box.replaceChildren();const timing=body.timing||{},choice=body.choice||{};
 box.append(userNode('h4',timing.partial?'Time recorded so far':'Where the time went'));
 if(!timing.available)box.append(userNode('p',timing.reason||'Timing details are unavailable.','insight-note'));
 else{const dl=userNode('dl',null,'insight-times');for(const row of timing.stages||[]){const wrap=userNode('div'),label=userNode('dt',row.label),value=userNode('dd',insightDuration(row.seconds)),track=userNode('div',null,'insight-track'),fill=userNode('span');track.setAttribute('aria-hidden','true');fill.style.width=Math.max(0,Math.min(100,Number(row.share_percent)||0))+'%';track.append(fill);wrap.append(label,value,track);dl.append(wrap)}box.append(dl,userNode('p','Total recorded: '+insightDuration(timing.recorded_seconds),'insight-note'),userNode('p',timing.note,'insight-note'))}
 box.append(userNode('h4','Why this encoding was chosen'));
 if(!choice.available)box.append(userNode('p',choice.reason||'No encoding-choice report is available.','insight-note'));
 else{box.append(userNode('p',choice.summary));for(const note of choice.notes||[])box.append(userNode('p',note,'insight-note'));
  if(choice.options?.length){const wrap=userNode('div',null,'insight-table-wrap'),table=userNode('table'),head=userNode('thead'),tr=userNode('tr'),tbody=userNode('tbody');wrap.tabIndex=0;wrap.setAttribute('aria-label','Encoding options comparison');for(const text of ['Option','Outcome','Sample reduction','Sample encoding time']){const th=userNode('th',text);th.scope='col';tr.append(th)}head.append(tr);for(const row of choice.options){const line=userNode('tr');for(const text of [row.name,row.outcome,Number.isFinite(row.sample_savings_percent)?row.sample_savings_percent.toFixed(1)+'%':'Not measured',insightDuration(row.encode_seconds)+(row.measured_samples?' ('+row.measured_samples+(row.expected_samples?' of '+row.expected_samples:'')+' clips)':'')])line.append(userNode('td',text));tbody.append(line)}table.append(head,tbody);wrap.append(table);box.append(userNode('p','Scroll sideways for all columns.','insight-note insight-scroll-hint'),wrap)}box.append(userNode('p',choice.note,'insight-note'))}
}
function attachResultInsights(ref){
 const box=userNode('section',null,'result-insights'),status=userNode('p'),content=userNode('div'),refresh=userNode('button','Refresh report');status.setAttribute('role','status');refresh.type='button';box.append(status,content,refresh);ref.details.insertBefore(box,ref.evidence);ref.insightGeneration=0;
 async function load(force=false){const job=ref.job;if(!job)return;const key=job.id+':'+job.state+':'+(job.finished||'');if(!force&&(ref.insightLoaded===key||ref.insightLoading===key))return;const generation=++ref.insightGeneration;ref.insightLoading=key;refresh.disabled=true;status.textContent='Loading time and encoding details…';content.replaceChildren();
  try{const body=await controlCall('result-insights',{job_id:job.requestId||job.id});if(generation!==ref.insightGeneration||ref.job.id!==job.id)return;renderResultInsights(content,body);ref.insightLoaded=key;status.textContent=''}catch(error){if(generation===ref.insightGeneration)status.textContent='Could not load this report. '+error.message}finally{if(generation===ref.insightGeneration){ref.insightLoading=null;refresh.disabled=false}}}
 refresh.addEventListener('click',()=>load(true));ref.details.addEventListener('toggle',()=>{if(ref.details.open)load()});ref.refreshInsights=()=>{if(ref.details.open)load()};
}
</script>'''
